def group_balls(s):
    # Initialize a list to store the groups of black and white balls
    black_groups = []
    white_groups = []

    # Iterate over the binary string s
    for i in range(len(s)):
        # If the current ball is black, add it to the black_groups list
        if s[i] == '0':
            black_groups.append(s[i])
        else:
            white_groups.append(s[i])

    # If the current ball is white, add it to the white_groups list
    if s[i] == '1':
        white_groups.append(s[i])

    # Return the minimum number of steps to group all the black balls to the right and all the white balls to the left
    return len(black_groups) - len(white_groups)

def distribute_candies(n, limit):
